using Xunit;

public class U04_AlarmsTest
{
    [Fact]
    public void HighVteAlarm_AboveThreshold_Active()
    {
        // Arrange
        var vteThreshold = 10;
        var currentBreathVte = 12;

        // Act
        var alarm = new Alarm(vteThreshold);
        alarm.ComputeVte(currentBreathVte);

        // Assert
        Assert.True(alarm.IsHighVteActive);
    }

    [Fact]
    public void LowVteAlarm_MediumPriority()
    {
        // Arrange
        var alarm = new Alarm();

        // Assert
        Assert.Equal(AlarmPriority.Medium, alarm.LowVtePriority);
    }

    [Fact]
    public void HighVteAlarm_MediumPriority()
    {
        // Arrange
        var alarm = new Alarm();

        // Assert
        Assert.Equal(AlarmPriority.Medium, alarm.HighVtePriority);
    }

    [Fact]
    public void VteComputedForEachBreath()
    {
        // Arrange
        var alarm = new Alarm();

        // Act
        alarm.ComputeVte(5);
        alarm.ComputeVte(8);

        // Assert
        Assert.Equal(2, alarm.VteHistory.Count);
    }

    [Fact]
    public void PressureHighAlarm_Cancelled_ReTriggerAfterTwoMinutes()
    {
        // Arrange
        var alarm = new Alarm();
        alarm.CancelPressureHighAlarm();

        // Act
        Thread.Sleep(120000);

        // Assert
        Assert.False(alarm.IsPressureHighActive);
    }

    [Fact]
    public void O2InputDisconnected_HighPriorityAlarm()
    {
        // Arrange
        var alarm = new Alarm();

        // Act
        alarm.HandleO2InputDisconnected();

        // Assert
        Assert.Equal(AlarmPriority.High, alarm.O2InputDisconnectedPriority);
    }

    [Fact]
    public void AllActiveAlarmsDisplayed()
    {
        // Arrange
        var alarm = new Alarm();
        alarm.ComputeVte(15);
        alarm.HandleO2InputDisconnected();

        // Act
        var activeAlarms = alarm.GetActiveAlarms();

        // Assert
        Assert.Equal(2, activeAlarms.Count);
    }

    [Fact]
    public void ConfirmedAlarmSettingsLogged()
    {
        // Arrange
        var alarm = new Alarm();
        alarm.ConfirmAlarmSettings();

        // Assert
        Assert.True(alarm.EventLog.Contains("Confirmed alarm settings"));
    }
}
